#!/usr/bin/env bash
#
# A wizard walks a human through a manual procedure, step by step.
# Generated by the /wizard skill.
#
# Everything above the "STAGES" marker is the wizard library: do not hand-edit
# it. Author the per-step stages below the marker.

set -euo pipefail

# ──────────────────────────────────────────────────────────────────────────
# Wizard library: delightful, consistent UX, identical across every wizard.
# ──────────────────────────────────────────────────────────────────────────

if [[ -t 1 ]] && command -v tput >/dev/null 2>&1 && [[ "$(tput colors 2>/dev/null || echo 0)" -ge 8 ]]; then
  BOLD=$(tput bold); DIM=$(tput dim); RESET=$(tput sgr0)
  BLUE=$(tput setaf 4); GREEN=$(tput setaf 2); YELLOW=$(tput setaf 3); RED=$(tput setaf 1)
else
  BOLD=""; DIM=""; RESET=""; BLUE=""; GREEN=""; YELLOW=""; RED=""
fi

# Author sets this at the top of the stages section.
TOTAL_STAGES=0

_STAGE_INDEX=0
ENV_FILE="${ENV_FILE:-.env}"
WRITTEN_ENV=()    # KEYs written to ENV_FILE this run
WRITTEN_SECRET=() # secret NAMEs set this run
SKIPPED=()        # things we couldn't do (e.g. gh missing)

# _clear wipes the terminal so only the current step is on screen. No-op when
# output isn't a terminal, so piped logs stay readable.
_clear() {
  [[ -t 1 ]] || return 0
  if command -v tput >/dev/null 2>&1; then tput clear; else printf '\033[2J\033[3J\033[H'; fi
}

# banner "Title" shows the opening frame: what this wizard does.
banner() {
  _clear
  printf '\n%s%s  %s%s\n' "$BOLD" "$BLUE" "$1" "$RESET"
  printf '%s  %s stages%s\n\n' "$DIM" "$TOTAL_STAGES" "$RESET"
  printf '%s  You drive the browser; this wizard tells you exactly what to do and\n' "$DIM"
  printf '  captures the values you copy back. Stop any time with Ctrl-C and re-run\n'
  printf '  later, since it remembers values already saved.%s\n' "$RESET"
  pause "Ready to start?"
}

# stage "Name" clears the screen, then announces a stage and shows progress.
# Clearing keeps only the current step on screen.
stage() {
  _clear
  _STAGE_INDEX=$((_STAGE_INDEX + 1))
  printf '\n%s%s▸ Stage %s/%s · %s%s\n' \
    "$BOLD" "$BLUE" "$_STAGE_INDEX" "$TOTAL_STAGES" "$1" "$RESET"
}

# say "..." prints a plain instruction line.
say()  { printf '  %s\n' "$1"; }
# step "..." is a numbered-feeling action the human takes in the browser.
step() { printf '  %s•%s %s\n' "$BLUE" "$RESET" "$1"; }
note() { printf '  %s%s%s\n' "$DIM" "$1" "$RESET"; }
warn() { printf '  %s⚠ %s%s\n' "$YELLOW" "$1" "$RESET"; }

# open_url URL opens it in the human's browser, cross-platform incl. WSL.
open_url() {
  local url="$1"
  printf '  %s↗ opening%s %s\n' "$GREEN" "$RESET" "$url"
  { if   command -v wslview     >/dev/null 2>&1; then wslview "$url"
    elif command -v explorer.exe >/dev/null 2>&1; then explorer.exe "$url"
    elif command -v xdg-open    >/dev/null 2>&1; then xdg-open "$url"
    elif command -v open        >/dev/null 2>&1; then open "$url"
    else warn "couldn't open a browser; visit it manually: $url"; fi
  } >/dev/null 2>&1 || warn "couldn't open a browser, so visit it manually: $url"
}

# pause "msg" waits for the human to confirm they've done the manual part.
pause() {
  printf '  %s%s%s ' "$DIM" "${1:-Press Enter to continue}" "$RESET"
  read -r _ || true
}

# confirm "question" is a y/N gate; returns success on yes.
confirm() {
  local reply=""
  printf '  %s? %s [y/N] ' "$YELLOW" "$1"
  read -r reply || true
  [[ "$reply" =~ ^[Yy] ]]
}

# _existing KEY: current value of KEY in ENV_FILE, if any.
_existing() {
  [[ -f "$ENV_FILE" ]] || return 1
  local line; line=$(grep -E "^${1}=" "$ENV_FILE" | tail -n1) || return 1
  printf '%s' "${line#*=}"
}

# ask KEY "Prompt" reads a value into $KEY. Offers the existing .env value as
# a default on re-runs (Enter keeps it). Visible input (non-secret).
ask() {
  local key="$1" prompt="$2" current input
  current=$(_existing "$key" || true)
  if [[ -n "$current" ]]; then
    printf '  %s%s%s %s[Enter keeps current]%s ' "$BOLD" "$prompt" "$RESET" "$DIM" "$RESET"
  else
    printf '  %s%s%s ' "$BOLD" "$prompt" "$RESET"
  fi
  read -r input || true
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# ask_secret KEY "Prompt" is like ask, but input is hidden.
ask_secret() {
  local key="$1" prompt="$2" current input
  current=$(_existing "$key" || true)
  if [[ -n "$current" ]]; then
    printf '  %s%s%s %s[Enter keeps current]%s ' "$BOLD" "$prompt" "$RESET" "$DIM" "$RESET"
  else
    printf '  %s%s%s ' "$BOLD" "$prompt" "$RESET"
  fi
  read -rs input || true
  printf '\n'
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# write_env KEY VALUE upserts KEY=VALUE into ENV_FILE (creates it; replaces
# any existing line). Idempotent.
write_env() {
  local key="$1" value="$2" tmp
  touch "$ENV_FILE"
  tmp=$(mktemp)
  grep -vE "^${key}=" "$ENV_FILE" > "$tmp" || true
  printf '%s=%s\n' "$key" "$value" >> "$tmp"
  mv "$tmp" "$ENV_FILE"
  WRITTEN_ENV+=("$key")
  printf '  %s✓ wrote%s %s → %s\n' "$GREEN" "$RESET" "$key" "$ENV_FILE"
}

# set_secret NAME VALUE sets a GitHub Actions repo secret via gh. Falls back
# to a warning (and records it) if gh is unavailable or unauthenticated.
set_secret() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if printf '%s' "$value" | gh secret set "$name" >/dev/null 2>&1; then
      WRITTEN_SECRET+=("$name")
      printf '  %s✓ set%s GitHub secret %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub secret $name (set it manually: gh secret set $name)")
  warn "skipped GitHub secret $name: gh not ready; set it later"
}

# set_var NAME VALUE sets a GitHub Actions repo variable (non-secret).
set_var() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if gh variable set "$name" --body "$value" >/dev/null 2>&1; then
      printf '  %s✓ set%s GitHub variable %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub variable $name")
  warn "skipped GitHub variable $name, gh not ready; set it later"
}

# finish clears, then shows a closing summary of everything configured.
finish() {
  _clear
  printf '\n%s%s  ✓ Setup complete%s\n' "$BOLD" "$GREEN" "$RESET"
  (( ${#WRITTEN_ENV[@]} ))    && note "wrote ${#WRITTEN_ENV[@]} value(s) to $ENV_FILE: ${WRITTEN_ENV[*]}"
  (( ${#WRITTEN_SECRET[@]} )) && note "set ${#WRITTEN_SECRET[@]} GitHub secret(s): ${WRITTEN_SECRET[*]}"
  if (( ${#SKIPPED[@]} )); then
    printf '\n'; warn "still to do by hand:"
    for s in "${SKIPPED[@]}"; do note "  - $s"; done
  fi
  printf '\n'
}

# ──────────────────────────────────────────────────────────────────────────
# STAGES: the human half of the TCC attribution experiment (issue #46).
#
# The harness in this directory is already built and verified. Everything that
# could be measured without a human has been. What is left needs a person at
# the machine, because the grant must be given in System Settings and the
# System Settings list itself is the main evidence.
#
# Nothing here is a credential. ENV_FILE is repurposed as an observations file
# so answers survive a Ctrl-C and re-run.
# ──────────────────────────────────────────────────────────────────────────

TOTAL_STAGES=10

PROTO="$(cd "$(dirname "${BASH_SOURCE[0]}")" && pwd)"
cd "$PROTO"
ENV_FILE="$PROTO/logs/observations.env"
mkdir -p "$PROTO/logs"

# grant_state <label> - echoes "granted" or "denied" by parsing the newest
# capture readstate.sh just wrote. Machine-checked, because a human reading the
# output and typing "yes" is exactly how the 2026-08-24 run was voided.
grant_state() {
  local f
  f=$(ls -t "$PROTO/logs"/state-*-"$1".json 2>/dev/null | head -n1) || true
  [[ -n "$f" ]] || { echo "unknown"; return; }
  /usr/bin/python3 - "$f" <<'PYEOF'
import json,sys
d=json.load(open(sys.argv[1]))
ax=d["axhelper"]["result"]; hk=d["hotkeyhelper"]["result"]
# axhelper/Accessibility is the hard requirement: it is the subject that
# actually answers the question. Input Monitoring never produced a System
# Settings entry in the 2026-08-24 run, so hotkeyhelper is advisory only -
# gating on it would block a run that can still decide the question.
ok = ax["reportedTrusted"] and ax["functionallyTrusted"]
print("granted" if ok else "denied")
sys.stderr.write("hotkeyhelper (advisory): reported=%s functional=%s\n"
                 % (hk["reportedGranted"], hk["functionallyGranted"]))
PYEOF
}

AX_PANE="x-apple.systempreferences:com.apple.preference.security?Privacy_Accessibility"
IM_PANE="x-apple.systempreferences:com.apple.preference.security?Privacy_ListenEvent"

banner "TCC attribution experiment (issue #46)"

# ── 1 ─────────────────────────────────────────────────────────────────────
stage "Preflight: the right checkout, and a warning"
say "Question: does each native helper hold its own Accessibility and Input"
say "Monitoring grant, or does the Electron host hold them for the helpers?"
printf '\n'
say "Running from: $PROTO"
if [[ "$PROTO" == *"/.claude/worktrees/"* ]]; then
  warn "This is a throwaway git worktree."
  say "TCC keys ad-hoc-signed apps partly on their path, so a grant given here"
  say "attaches to a directory that gets deleted. Run this from your main"
  say "checkout instead: ~/workspace/zazai840/openstream/prototypes/tcc-attribution-46"
  confirm "Continue anyway?" || exit 1
fi
printf '\n'
warn "The grants you are about to give are REAL TCC entries on this Mac."
say "Stage 10 removes them again. Please do not stop before it."
pause "Understood - press Enter."

# ── 2 ─────────────────────────────────────────────────────────────────────
stage "Build the probe"
say "Builds build/TCCProbe.app: an ad-hoc-signed Electron bundle with its own"
say "bundle id, containing two stub Swift helpers spawned over stdio."
printf '\n'
if [[ -d "$PROTO/build/TCCProbe.app" ]]; then
  warn "A build already exists."
  say "Rebuilding moves the host CDHash, and THAT DESTROYS ANY GRANT YOU"
  say "ALREADY HAVE. Re-running this wizard from the top is what voided the"
  say "2026-08-24 run: the arms then measured denied -> denied and decided"
  say "nothing. If you are resuming with a grant in place, keep the build."
  printf '\n'
  if confirm "Rebuild from scratch anyway (destroys any existing grant)?"; then
    ./build.sh 2>&1 | tail -n 8
  else
    say "Keeping the existing build."
  fi
else
  ./build.sh 2>&1 | tail -n 8
fi
printf '\n'
pause "Build done - press Enter."

# ── 3 ─────────────────────────────────────────────────────────────────────
stage "Baseline, before any grant exists"
say "Captures all three subjects with no clicking. Everything should be denied."
printf '\n'
./readstate.sh baseline || true
printf '\n'
say "Check: every 'reported' and 'functional' reads False, and 'responsible'"
say "names TCCProbe itself, NOT your terminal or editor."
if confirm "Does the baseline look like that?"; then
  write_env BASELINE_CLEAN "yes"
else
  ask BASELINE_ANOMALY "What was different? (one line):"
  write_env BASELINE_CLEAN "no"
  write_env BASELINE_ANOMALY "$BASELINE_ANOMALY"
fi

# ── 4 ─────────────────────────────────────────────────────────────────────
stage "Trigger the two permission prompts"
say "The app window reads all three subjects on launch and after every click."
printf '\n'
open build/TCCProbe.app || true
step "Click 'Spawn axhelper (--prompt)'. A macOS Accessibility prompt appears."
step "Click 'Spawn hotkeyhelper (--prompt)'. An Input Monitoring prompt appears."
step "In each prompt choose 'Open System Settings' (or dismiss it - the entry"
say "  is added to the list either way)."
printf '\n'
note "Leave the app running. Do not grant anything yet - the next two stages"
note "are about reading the list BEFORE you flip the switches."
pause "Both buttons clicked - press Enter."

# ── 5 ─────────────────────────────────────────────────────────────────────
stage "THE DECISIVE OBSERVATION: what does Accessibility name?"
say "This single reading answers most of the question on its own."
open_url "$AX_PANE"
step "Look at the list of apps under Accessibility."
step "Find the entry (or entries) this prototype just added."
printf '\n'
say "  If it says 'TCCProbe'      → the Electron host holds the grant."
say "  If it says 'axhelper'      → the helper holds its own grant."
say "  If BOTH appear             → say so; that is a real and interesting result."
printf '\n'
ask AX_ENTRY_NAMES "Exactly what name(s) appear? "
write_env AX_ENTRY_NAMES "$AX_ENTRY_NAMES"
step "Now turn the switch ON for every entry the prototype added."
pause "Accessibility granted - press Enter."

# ── 6 ─────────────────────────────────────────────────────────────────────
stage "What does Input Monitoring name?"
open_url "$IM_PANE"
step "Look at the list under Input Monitoring."
printf '\n'
say "  'TCCProbe' → host holds it.  'hotkeyhelper' → helper holds its own."
printf '\n'
ask IM_ENTRY_NAMES "Exactly what name(s) appear? "
write_env IM_ENTRY_NAMES "$IM_ENTRY_NAMES"
step "Turn the switch ON for every entry the prototype added."
note "macOS may ask you to quit and reopen TCCProbe. If it does, quit it."
pause "Input Monitoring granted - press Enter."

# ── 7 ─────────────────────────────────────────────────────────────────────
stage "Confirm the grant is real"
say "Re-reads all three subjects. This proves the grant landed and is not a"
say "stale prompt, so the two rebuild arms start from a known-good state."
printf '\n'
./readstate.sh granted || true
printf '\n'
GRANT_STATE="$(grant_state granted)"
write_env GRANT_CONFIRMED "$GRANT_STATE"
if [[ "$GRANT_STATE" != "granted" ]]; then
  printf '\n'
  warn "MACHINE CHECK FAILED: axhelper is not granted in the capture above."
  warn "The two arms below would measure denied -> denied and decide"
  warn "nothing, so this wizard stops here rather than record a void result."
  printf '\n'
  say "Fix it, then re-run this wizard and KEEP the existing build at stage 2:"
  step "Grant TCCProbe in System Settings > Privacy & Security > Accessibility."
  step "Do not run build.sh again - that moves the host CDHash and drops it."
  printf '\n'
  exit 1
fi
say "Machine check passed: both helpers granted. The arms can decide something."

# ── 8 ─────────────────────────────────────────────────────────────────────
stage "Arm 1: rebuild the JavaScript, leave the helpers untouched"
say "This is the arm that decides the blast radius of an ordinary code change."
printf '\n'
./rebuild-js.sh 2>&1 | tail -n 6
printf '\n'
./readstate.sh arm1-js || true
printf '\n'
say "  Helpers still pass, host drops → grants are PER-HELPER."
say "  All three drop                 → the ELECTRON BUNDLE holds them."
say "  Nothing drops                  → a JS rebuild costs no grants at all."
printf '\n'
ask ARM1_RESULT "Which of those three happened? "
write_env ARM1_RESULT "$ARM1_RESULT"

# ── 9 ─────────────────────────────────────────────────────────────────────
stage "Arm 2: rebuild the helpers, leave the JavaScript untouched"
say "The helpers are recompiled with a new build tag, so their CDHash really"
say "moves. This decides whether the entry is keyed to helper code identity."
printf '\n'
./rebuild-helpers.sh 2>&1 | tail -n 6
printf '\n'
./readstate.sh arm2-helpers || true
printf '\n'
say "  Helpers now fail   → the entry IS keyed to the helper's own CDHash."
say "  Helpers still pass → it is not."
printf '\n'
ask ARM2_RESULT "Which happened? "
write_env ARM2_RESULT "$ARM2_RESULT"
note "If a new prompt appeared during this stage, that itself is the answer."
ask ARM2_REPROMPTED "Did macOS re-prompt for permission? (yes/no) "
write_env ARM2_REPROMPTED "$ARM2_REPROMPTED"

# ── 10 ────────────────────────────────────────────────────────────────────
stage "tccutil reset, then clean up"
say "Already measured without a grant: the host bundle id is a valid target"
say "and both helpers have no bundle id at all. Now: what does it CLEAR?"
printf '\n'
if confirm "Run tccutil reset against the prototype's bundle id now?"; then
  tccutil reset Accessibility dev.openstream.prototype.tccprobe || true
  tccutil reset ListenEvent   dev.openstream.prototype.tccprobe || true
  printf '\n'
  ./readstate.sh after-tccutil || true
  printf '\n'
  ask TCCUTIL_EFFECT "What did it clear - host only, helpers too, or nothing? "
  write_env TCCUTIL_EFFECT "$TCCUTIL_EFFECT"
fi
printf '\n'
warn "Cleanup: these are real TCC entries. Remove them now."
open_url "$AX_PANE"
step "Remove every prototype entry from Accessibility (select, then '-')."
open_url "$IM_PANE"
step "Remove every prototype entry from Input Monitoring."
pause "Entries removed - press Enter."
if confirm "Delete build/ as well?"; then
  rm -rf "$PROTO/build"
  say "build/ deleted."
fi

finish
printf '  %sObservations saved to:%s %s\n' "$BOLD" "$RESET" "$ENV_FILE"
printf '  %sLog captures:%s %s\n\n' "$BOLD" "$RESET" "$PROTO/logs/"
say "Next: hand that observations file and the logs/ JSON back to Claude, which"
say "will fill in RESULTS.md and write the verdict for issue #46."
printf '\n'
